        Aha, i ide otprilike ovako:

        form_center( dialog, &x, &y, &w, &h );
        form_dial( FMD_START, x, y, w, h, x, y, w, h );
        objc_draw( dialog, 0, 2, x, y, w, h );
        /* Ovde se predaje kontrola AES-u       */
