/* Eksterne funkcije */

extern void play(long song, long vreme, long frekvencija);

void main(void)
{
      FILE *pesma;
      char *bafer;

      if((pesma = fopen("D:\\SONGS\\PESMA.SNG", "rb")) == NULL) {
            fprintf(stderr, "Can't open song file!");
            exit(1);
      }

      if((bafer = malloc(dužina_datoteke_pesma) == NULL) {
            fprintf(stderr, "Not enough memory!"):
            fclose(pesma):
            exit(2);
      }

      fread(bafer, dužina_datoteke_pesma, 1, pesma);
      fclose(pesma);
      play((long) bafer, 60, 10);
      free(bafer);
}

      E, sad ako znaš gde će Turbo C baciti adresu bafera i druga dva
parametra, napiši tako rutinu koja "svira". Ja ne znam da li baca na stek
redom ili adresu šalje kroz neki registar. Nadam se da iako nisi ljubitelj
C-a možeš da "pročitaš" gornji primer.

